'use strict';
const solutions=[{label:'ВЛАСНА ГЕНЕРАЦІЯ',title:'Більше власної енергії — у власному споживанні.',text:'Зіставляйте профіль генерації СЕС із навантаженням підприємства. Розумійте, коли надлишок можна накопичити, а коли енергію доведеться купувати з мережі.',task:'Узгодити генерацію, навантаження та можливість накопичення.',logic:'Спільний баланс енергії, прогноз і план використання доступних активів.',audit:'Профіль навантаження, потужність СЕС, обмеження експорту, наявність BESS.'},{label:'КЕРУВАННЯ НАКОПИЧЕННЯМ',title:'Батарея працює за економікою. Із потрібним резервом.',text:'Переносьте купівлю енергії між годинами, якщо тариф і технічні умови роблять це доцільним. Окремо визначайте запас для автономності та допустиме використання ресурсу.',task:'Зменшити дорогу купівлю, зберігши погоджений резерв.',logic:'Графік заряду й розряду з урахуванням ціни, ККД, навантаження та лімітів.',audit:'Корисна ємність, потужність, SoC, доступ до BMS та команд інвертора.'},{label:'ТЕХНІЧНИЙ ОБЛІК',title:'Побачте об’єкт за цифрами. Не за окремими застосунками.',text:'Об’єднайте точки споживання та генерації в узгоджену картину. Спільні дані допомагають енергетику контролювати режими, а керівнику — бачити структуру витрат.',task:'Звести розрізнені показники та зрозуміти енергобаланс.',logic:'Збір показників, історія, порівняння періодів і аналіз відхилень.',audit:'Схема обліку, перелік лічильників, інтерфейси та якість доступних даних.'}];
const tabs=[...document.querySelectorAll('[data-solution]')];function selectSolution(i,focus=false){tabs.forEach((b,j)=>{b.setAttribute('aria-selected',String(i===j));b.tabIndex=i===j?0:-1});const s=solutions[i];for(const key of ['label','title','text','task','logic','audit'])document.getElementById('solution-'+key).textContent=s[key];document.getElementById('solution-content').setAttribute('aria-labelledby','tab-'+i);document.getElementById('solution-content').dataset.scenario=String(i);document.querySelector('.scenario-asset-map>span').textContent=['СЕС','BESS','Облік'][i];if(focus)tabs[i].focus()}tabs.forEach((b,i)=>{b.addEventListener('click',()=>selectSolution(i));b.addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();selectSolution(e.key==='Home'?0:e.key==='End'?2:(i+(e.key==='ArrowRight'?1:2))%3,true)}})});selectSolution(0);
const menu=document.querySelector('.menu-toggle'),nav=document.getElementById('navigation');
const compactNavigation=window.matchMedia('(max-width:1020px)');
const menuOpenLabel=menu.getAttribute('aria-label');
const menuLinks=[...nav.querySelectorAll('a')];
function setMenuOpen(open,restoreFocus=false){
 const expanded=compactNavigation.matches&&open;
 nav.classList.toggle('open',expanded);
 menu.setAttribute('aria-expanded',String(expanded));
 menu.setAttribute('aria-label',expanded?'Закрити меню':menuOpenLabel);
 nav.inert=compactNavigation.matches&&!expanded;
 if(restoreFocus)menu.focus();
}
menu.addEventListener('click',event=>{
 const open=menu.getAttribute('aria-expanded')!=='true';
 setMenuOpen(open);
 if(open&&event.detail===0)menuLinks[0].focus();
});
menuLinks.forEach(link=>link.addEventListener('click',()=>{
 menuLinks.forEach(other=>other.removeAttribute('aria-current'));
 link.setAttribute('aria-current','location');
 setMenuOpen(false);
}));
document.addEventListener('click',event=>{
 if(menu.getAttribute('aria-expanded')==='true'&&!nav.contains(event.target)&&!menu.contains(event.target))setMenuOpen(false);
});
document.addEventListener('keydown',event=>{
 if(menu.getAttribute('aria-expanded')!=='true')return;
 if(event.key==='Escape'){event.preventDefault();setMenuOpen(false,true);}
 if(event.key==='Tab'){
  if(!event.shiftKey&&document.activeElement===menu){event.preventDefault();menuLinks[0].focus();}
  else if(event.shiftKey&&document.activeElement===menuLinks[0]){event.preventDefault();menu.focus();}
  else if(!event.shiftKey&&document.activeElement===menuLinks[menuLinks.length-1]){event.preventDefault();menu.focus();}
 }
});
document.querySelector('.header').addEventListener('focusout',event=>{
 if(menu.getAttribute('aria-expanded')==='true'&&event.relatedTarget&&!document.querySelector('.header').contains(event.relatedTarget))setMenuOpen(false);
});
compactNavigation.addEventListener('change',()=>setMenuOpen(false));
setMenuOpen(false);
const prices=[3.2,2.9,2.6,2.4,2.5,2.8,3.4,4.3,5.1,5.4,5.2,4.6,4.1,3.9,4.4,5.3,6.7,7.6,8.2,8,7.4,6.2,4.8,3.8],chart=document.getElementById('price-chart');
function kind(h){return h<6?'charge':h>=17&&h<=21?'discharge':'hold'}prices.forEach((price,h)=>{const b=document.createElement('button');b.style.height=(price/9*100)+'%';b.dataset.kind=kind(h);b.title=`${String(h).padStart(2,'0')}:00 — ${formatDemoNumber(price)} ₴/кВт·год`;b.setAttribute('aria-label',b.title);b.setAttribute('aria-pressed','false');b.addEventListener('click',()=>setHour(h));chart.appendChild(b)});
function setHour(h){if(typeof stopDayPlayback==='function'&&!dayPlaybackTick)stopDayPlayback();const time=String(h).padStart(2,'0')+':00';document.getElementById('hour').value=h;document.getElementById('hour-label').textContent=time;document.getElementById('selected-hour').textContent=time;document.getElementById('decision-price').textContent=formatDemoNumber(prices[h])+' ₴';const k=kind(h);document.getElementById('decision-title').textContent=k==='charge'?'Зарядити за нижчою ціною':k==='discharge'?'Заміщувати дорогу купівлю':h>=22?'Зберігати резерв':'Зберігати гнучкість';document.getElementById('decision-text').textContent=k==='charge'?'У цьому прикладі нічна ціна нижча. План передбачає заряд, якщо очікувана різниця покриває втрати та ресурс батареї.':k==='discharge'?'Накопичена енергія покриває частину навантаження у дорогі години. Розряд обмежений потужністю та погодженим резервом.':h>=22?'У цьому прикладі період розряду завершено. Накопичувач зберігає погоджений резерв до наступного циклу планування.':'У денному сценарії пріоритет — споживання генерації СЕС. Надлишок можна спрямувати в накопичувач, якщо це допускає його стан.';[...chart.children].forEach((b,i)=>b.setAttribute('aria-pressed',String(i===h)));document.dispatchEvent(new CustomEvent('operion:hour',{detail:{hour:h,kind:k}}))}document.getElementById('hour').addEventListener('input',e=>setHour(Number(e.target.value)));setHour(18);
document.getElementById('year').textContent=new Date().getFullYear();

// Product demonstration. Explicit scenarios, no live telemetry or equipment commands.
const demoPhases=[{time:'02:00 / НІЧ',solar:0,load:110,grid:190,soc:38,battery:'Заряд 80 кВт',badge:'ПЕРЕНЕСЕННЯ КУПІВЛІ',action:'Підготувати запас на дорожчі години.',reason:'У демонстраційному плані мережа покриває 110 кВт навантаження та 80 кВт заряду. Доцільність залежить від тарифу, втрат і ресурсу.',balance:'Баланс: 190 = 110 + 80 кВт',description:'Мережа забезпечує 190 кВт: 110 споживає підприємство, 80 спрямовується на заряд батареї.',solarActive:false,gridActive:true,reverse:false},{time:'12:00 / ДЕНЬ',solar:240,load:180,grid:0,soc:62,battery:'Заряд 60 кВт',badge:'ВЛАСНА ГЕНЕРАЦІЯ',action:'Використати сонце. Накопичити надлишок.',reason:'Генерація перевищує поточне навантаження. У цьому сценарії 180 кВт використовує об’єкт, а 60 кВт спрямовується на заряд BESS.',balance:'Баланс: 240 = 180 + 60 кВт',description:'СЕС генерує 240 кВт: 180 споживає підприємство, 60 спрямовується на заряд батареї. Купівля з мережі — 0 кВт.',solarActive:true,gridActive:false,reverse:false},{time:'18:00 / ПІК',solar:35,load:180,grid:0,soc:74,battery:'Розряд 145 кВт',badge:'ЗАМІЩЕННЯ ДОРОГОЇ КУПІВЛІ',action:'Покрити навантаження енергією BESS.',reason:'35 кВт від СЕС і 145 кВт із накопичувача покривають 180 кВт споживання. Розряд обмежений погодженим резервом і потужністю.',balance:'Баланс: 35 + 145 = 180 кВт',description:'СЕС забезпечує 35 кВт, батарея віддає 145 кВт, підприємство споживає 180 кВт. Купівля з мережі — 0 кВт.',solarActive:true,gridActive:false,reverse:true}];
const phaseButtons=[...document.querySelectorAll('[data-phase]')];let demoPhase=1,demoTimer=null;const reducedMotion=window.matchMedia('(prefers-reduced-motion: reduce)');
function showDemoPhase(i){demoPhase=i;const p=demoPhases[i];for(const key of ['solar','load','grid','soc'])document.getElementById('demo-'+key).textContent=p[key];for(const key of ['solar','load','grid'])document.getElementById('node-'+key).textContent=p[key]+' кВт';document.getElementById('node-battery').textContent=p.battery;for(const key of ['time','badge','action','reason','balance'])document.getElementById('demo-'+key).textContent=p[key];document.getElementById('flow-desc').textContent=p.description;document.getElementById('demo-soc-bar').style.width=p.soc+'%';document.getElementById('path-solar').classList.toggle('flow-inactive',!p.solarActive);document.getElementById('path-grid').classList.toggle('flow-inactive',!p.gridActive);document.getElementById('path-battery').classList.toggle('flow-reverse',p.reverse);phaseButtons.forEach((b,j)=>b.setAttribute('aria-pressed',String(i===j)));document.dispatchEvent(new CustomEvent('operion:phase',{detail:{phase:i}}));}
const demoPlay=document.getElementById('demo-play');function stopDemo(){if(demoTimer)clearInterval(demoTimer);demoTimer=null;demoPlay.setAttribute('aria-pressed','false');demoPlay.setAttribute('aria-label','Увімкнути автоматичну зміну сценаріїв');demoPlay.textContent='▶ Автопоказ'}function startDemo(){if(demoTimer)return;demoPlay.setAttribute('aria-pressed','true');demoPlay.setAttribute('aria-label','Призупинити автоматичну зміну сценаріїв');demoPlay.textContent='Ⅱ Пауза';demoTimer=setInterval(()=>showDemoPhase((demoPhase+1)%3),6500)}phaseButtons.forEach((b,i)=>b.addEventListener('click',()=>{stopDemo();showDemoPhase(i)}));demoPlay.addEventListener('click',()=>demoTimer?stopDemo():startDemo());document.addEventListener('visibilitychange',()=>{if(document.hidden)stopDemo()});reducedMotion.addEventListener('change',e=>{if(e.matches)stopDemo()});showDemoPhase(1);
const businessTypes=[{category:'ВИРОБНИЧІ ПІДПРИЄМСТВА',title:'Енергія має працювати за графіком виробництва.',problem:'Зміни, різні ділянки та власна генерація створюють складний профіль споживання. Ручний розклад накопичувача не завжди збігається з фактичним навантаженням.',person:'Енергетик · технічний директор · фінансовий керівник',value:'Єдина картина по вводах, генерації та активам. План роботи BESS з урахуванням виробничого профілю, тарифу й погодженого резерву.',scenario:'Використання СЕС у власному споживанні та перенесення частини купівлі енергії між годинами — без втручання в технологічний процес.',data:'Погодинний профіль споживання, графік змін, потужність СЕС/BESS, ліміти приєднання та доступні інтерфейси.'},{category:'ЛОГІСТИКА ТА ХОЛОДНІ ЛАНЦЮГИ',title:'Холод не чекає. Резерв і витрати потрібно узгодити.',problem:'Холодильні комплекси й склади мають тривале навантаження. Економічний режим накопичувача повинен враховувати критичне споживання та запас автономності.',person:'Керівник комплексу · енергетик · служба експлуатації',value:'Облік навантаження холодильних установок і загального балансу. Прозорий стан BESS та сценарій його використання з окремим обмеженням резерву.',scenario:'СЕС покриває денне навантаження, BESS переносить частину купівлі на вигідніші години. Автономність визначається окремо, а не обіцяється за замовчуванням.',data:'Критичне навантаження, потрібна тривалість резерву, потужність інвертора, ємність батареї та фактичний режим роботи.'},{category:'АГРО ТА ПЕРЕРОБКА',title:'Сезонне навантаження потребує гнучкого плану.',problem:'Під час сезону споживання елеватора чи переробного підприємства змінюється. Однакові налаштування на весь рік можуть не відповідати реальному режиму.',person:'Власник підприємства · головний інженер · енергетик',value:'Історія споживання по періодах, зіставлення з генерацією та планування доступних енергоактивів відповідно до сезонного профілю.',scenario:'Власна сонячна енергія для денного процесу, заряд BESS у погоджені періоди й розряд за потребами об’єкта. Технологічні лінії не перемикаються без окремого проєкту.',data:'Сезонні графіки, режим основного обладнання, джерела генерації, тариф та можливості обліку.'},{category:'РИТЕЙЛ І ТОРГОВІ ОБ’ЄКТИ',title:'Погодьте денну генерацію з вечірнім споживанням.',problem:'Сонячна генерація, холодильне обладнання, освітлення й вечірня активність створюють різні профілі навантаження. Дані часто залишаються в окремих системах.',person:'Директор об’єкта · енергетик мережі · фінансовий менеджер',value:'Баланс енергії, порівняння періодів і план використання BESS. Керівник бачить структуру витрат, інженер — умови та межі сценарію.',scenario:'Використання власної генерації та заміщення частини дорожчої купівлі у вечірні години, якщо тариф і навантаження дають позитивну економіку.',data:'Графік роботи, денне та вечірнє навантаження, схема обліку, тариф, наявні СЕС і накопичувач.'},{category:'КОМЕРЦІЙНА НЕРУХОМІСТЬ',title:'Перетворіть розрізнені показники на баланс будівлі.',problem:'Кілька вводів, спільні зони та різні графіки користувачів ускладнюють енергетичний облік бізнес-центру, готелю або комплексу.',person:'Керуюча компанія · служба експлуатації · власник нерухомості',value:'Технічний облік по погоджених точках, історія генерації та споживання, порівняння періодів. За наявності керованих активів — окремий модуль оптимізації.',scenario:'Почати зі збору даних і контролю відхилень. Після оцінки профілю додати узгоджений план роботи СЕС та BESS.',data:'Схема вводів, перелік лічильників, спільні навантаження, інтерфейси. Розрахунки з орендарями не замінюються технічним обліком.'},{category:'ГРУПИ ОБ’ЄКТІВ',title:'Спільна логіка оцінки. Власні правила кожного майданчика.',problem:'Окремі застосунки, різні інвертори та відмінні тарифи ускладнюють порівняння об’єктів і пошук причин відхилень.',person:'Енергоменеджер групи · технічний директор · керівник мережі',value:'Узгоджений підхід до збору показників, аналізу періодів і визначення сценаріїв. Обсяг консолідації та інтеграцій фіксуємо в проєкті.',scenario:'Пілот на одному майданчику, перевірка даних і ефекту. Далі — тиражування погодженого рішення з урахуванням особливостей кожного об’єкта.',data:'Перелік майданчиків, моделі пристроїв, доступи, якість даних і тарифи. Можливість централізованого керування перевіряється окремо.'}];
const businessButtons=[...document.querySelectorAll('[data-business]')];function selectBusiness(i,focus=false){businessButtons.forEach((b,j)=>{b.setAttribute('aria-selected',String(j===i));b.tabIndex=j===i?0:-1});const b=businessTypes[i];for(const k of ['category','title','problem','person','value','scenario','data'])document.getElementById('business-'+k).textContent=b[k];const panel=document.getElementById('business-panel');panel.setAttribute('aria-labelledby','business-tab-'+i);panel.classList.remove('content-enter');void panel.offsetWidth;panel.classList.add('content-enter');if(focus)businessButtons[i].focus()}
businessButtons.forEach((b,i)=>{b.addEventListener('click',()=>selectBusiness(i));b.addEventListener('keydown',e=>{if(['ArrowRight','ArrowLeft','Home','End'].includes(e.key)){e.preventDefault();selectBusiness(e.key==='Home'?0:e.key==='End'?5:(i+(e.key==='ArrowRight'?1:5))%6,true)}})});selectBusiness(0);
// Progressive scroll reveals: content stays available when motion is reduced or observers are unsupported.
if(!reducedMotion.matches&&'IntersectionObserver' in window){const sections=[...document.querySelectorAll('.module-grid article,.steps article,.software-deliverables p')];sections.forEach(el=>el.classList.add('reveal-item'));document.documentElement.classList.add('has-reveal');const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('is-visible');observer.unobserve(e.target)}}),{threshold:.08});sections.forEach(el=>observer.observe(el));}
